import type { Occupation, Region, Town } from '../types'
import data from './reference.json'

// Jobs, regions and towns from the real model (gridskills). Generated by
// scripts/export_app_data.py; rerun it after the model's outputs are rebuilt.

export type Sector = 'power_trades' | 'construction' | 'tech' | 'finance' | 'education' | 'retail' | 'health' | 'admin'

/** Rough sector from the NOC code, used only for sample postings (employers and pay). */
function sectorOf(code: string): Sector {
  const two = code.slice(0, 2)
  switch (code[0]) {
    case '0':
    case '1':
      return two === '13' || two === '14' || code === '0001' ? 'admin' : 'finance'
    case '2':
      return 'tech'
    case '3':
      return 'health'
    case '4':
      return 'education'
    case '5':
      return 'admin'
    case '6':
      return 'retail'
    case '7':
      return code.startsWith('72') ? 'power_trades' : 'construction'
    default:
      return 'power_trades'
  }
}

export const OCCUPATIONS: (Occupation & { sector: Sector })[] = data.occupations.map((o) => ({
  ...o,
  sector: sectorOf(o.code),
}))

export const REGIONS: (Region & {
  workforce: number | null
  jobsPerYear: { low: number; base: number; high: number } | null
  topTechnologies: { technology: string; jobs: number }[]
})[] = data.regions.map((r) => ({
  id: r.id,
  name: r.name,
  short: r.short,
  workforce: r.workforce ?? null,
  jobsPerYear: r.jobsPerYear ?? null,
  topTechnologies: r.topTechnologies ?? [],
}))

export const TOWNS: Town[] = data.towns.map((t) => ({ name: t.name, regionId: t.region }))

/** Everyday words that map to a job ("nurse" -> 3130), from gridskills.api.ALIASES */
export const ALIASES: Record<string, string> = data.aliases

export const PROVINCE = data.province
export const HORIZON = data.horizon as [number, number]
export const SNAPSHOT = data.snapshot

export const findOccupation = (code: string) => OCCUPATIONS.find((o) => o.code === code)
export const findRegion = (id: string) => REGIONS.find((r) => r.id === id)
export const findTown = (name: string) => TOWNS.find((t) => t.name === name)

/** Plain Region (without the overview numbers) for storing in alerts and pathways */
export const regionRef = (id: string): Region | undefined => {
  const r = findRegion(id)
  return r && { id: r.id, name: r.name, short: r.short }
}

export const TECH_LABEL: Record<string, string> = {
  data_centre: 'Data centres',
  gas: 'Gas power',
  solar: 'Solar',
  solar_storage: 'Solar with storage',
  wind: 'Wind',
  storage: 'Battery storage',
  storage_long: 'Long-duration storage',
  cogen: 'Cogeneration',
  industrial_load: 'Industrial sites',
  distribution_load: 'Local grid growth',
  other_gen: 'Other generation',
}

/** Matches typed text against job titles and aliases, for the job pickers. */
export function matchesOccupation(option: Occupation, input: string): boolean {
  const q = input.trim().toLowerCase()
  if (!q) return true
  if (option.title.toLowerCase().includes(q) || option.code.startsWith(q)) return true
  const singular = q.endsWith('s') ? q.slice(0, -1) : q
  return ALIASES[q] === option.code || ALIASES[singular] === option.code
}
